-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 3
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 3 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 03', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 03 (10 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-PRATICA-AULA-03.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique a diferença entre Internet e World Wide Web.', 0.5, 'Internet é a infraestrutura física global de redes (cabos, roteadores, servidores, protocolo TCP/IP). A World Wide Web é um serviço de páginas em hipertexto (HTML, HTTP) que funciona sobre a Internet, criado por Tim Berners-Lee em 1989. O navegador é só o programa que acessa a Web.', 'Nota cheia: diferença correta entre Internet e Web. Metade: diferença incompleta. Zero: trata como iguais.'),
      (v_atividade, 1, 2, 'Explique o que acontece desde que você digita o endereço até a página aparecer, citando o DNS, a requisição HTTPS e a renderização.', 0.5, 'O DNS traduz o nome do site para o endereço IP do servidor; o navegador envia a requisição HTTPS (segura) ao servidor; o servidor responde com HTML, CSS e scripts; o navegador renderiza esses códigos e mostra a página.', 'Nota cheia: DNS + requisição + renderização na ordem. Metade: dois dos três. Zero: um ou nenhum.'),
      (v_atividade, 2, 1, 'Explique o que são cache e cookies e por que limpá-los pode resolver o problema do portal.', 0.5, 'Cache: arquivos das páginas guardados no computador para carregar mais rápido. Cookies: pequenos arquivos que salvam preferências e o login. Se estiverem antigos ou corrompidos, a página aparece desatualizada e o login falha; limpar força o navegador a baixar a versão atual e refazer o login (e remove rastreadores).', 'Nota cheia: define os dois + por que limpar resolve. Metade: só definições ou só a solução. Zero: sem relação.'),
      (v_atividade, 2, 2, 'Explique o que a navegação anônima realmente faz e por que o colega está errado.', 0.5, 'A guia anônima apenas não salva histórico, formulários e cookies no computador. O tráfego continua visível para o provedor, o administrador da rede da empresa (TI) e os servidores, que registram o IP. Não garante anonimato nem substitui antivírus.', 'Nota cheia: o que ela faz + o que não esconde. Metade: só um dos dois. Zero: concorda com o colega.'),
      (v_atividade, 3, 1, 'Descreva as três fases do buscador: rastreamento, indexação e ranqueamento.', 0.6, 'Rastreamento: robôs (spiders) percorrem links e coletam as páginas. Indexação: o conteúdo e as palavras-chave são organizados num catálogo (base de dados). Ranqueamento: algoritmos ordenam os resultados por relevância e autoridade. O buscador consulta esse catálogo, não a internet em tempo real.', 'Nota cheia: as três fases corretas. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 3, 2, 'Explique por que o primeiro resultado nem sempre é o mais confiável e o que você deve fazer antes de usar a informação.', 0.4, 'O ranqueamento usa critérios como popularidade, palavras-chave e anúncios patrocinados; um site bem posicionado pode ser comercial, desatualizado ou sem autoria. Antes de usar, é preciso avaliar a fonte (autor, data, instituição, provas — método CRAAP) e comparar com outras fontes.', 'Nota cheia: motivo + avaliar/comparar a fonte. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 4, 1, 'Escreva uma busca que exija os termos palete e armazenagem e exclua móveis e artesanato.', 0.5, 'Ex.: palete AND armazenagem -móveis -artesanato (ou palete AND armazenagem NOT móveis NOT artesanato).', 'Nota cheia: exige os dois termos e exclui os dois. Metade: falta uma exclusão ou o AND. Zero: busca sem operadores.'),
      (v_atividade, 4, 2, 'Escreva uma busca que encontre páginas com empilhadeira ou paleteira e explique a diferença entre AND e OR.', 0.5, 'Ex.: empilhadeira OR paleteira. AND exige que todos os termos estejam na página (restringe a busca); OR aceita qualquer um dos termos (amplia a busca).', 'Nota cheia: busca com OR + diferença correta. Metade: só um dos dois. Zero: confunde os operadores.'),
      (v_atividade, 5, 1, 'Escreva a busca para os documentos oficiais em PDF com a expressão exata, explicando cada operador usado.', 0.6, '"segurança no trabalho com empilhadeiras" site:gov.br filetype:pdf. Aspas: frase exata; site:gov.br: só sites do governo; filetype:pdf: só arquivos PDF.', 'Nota cheia: os três operadores corretos e explicados. Metade: dois operadores certos ou os três sem explicação. Zero: um ou nenhum.'),
      (v_atividade, 5, 2, 'Escreva a busca para encontrar materiais de universidades brasileiras sobre armazenagem.', 0.4, 'Ex.: armazenagem site:edu.br (pode acrescentar filetype:pdf ou "armazenagem de paletes"). Também vale citar Google Acadêmico, SciELO ou Periódicos CAPES como complemento.', 'Nota cheia: usa site:edu.br (ou .edu.br) com o tema. Metade: indica repositório acadêmico sem o operador. Zero: busca sem filtro de domínio.'),
      (v_atividade, 6, 1, 'Explique os critérios do método CRAAP (atualidade, relevância, autoridade, precisão e propósito).', 0.5, 'Atualidade: quando foi publicado ou revisado. Relevância: se atende ao tema e ao nível do relatório. Autoridade: quem é o autor e a instituição. Precisão e propósito: se os dados são comprovados, com referências, e se há viés comercial ou sensacionalista.', 'Nota cheia: os quatro grupos de critérios explicados. Metade: dois ou três. Zero: um ou nenhum.'),
      (v_atividade, 6, 2, 'Aplique os critérios às fontes A e B e diga qual você usaria no relatório, justificando.', 0.5, 'Fonte A: desatualizada (2014), sem autor (sem autoridade), muitos anúncios e título sensacionalista (propósito comercial, sem provas) — não usar. Fonte B: atual (2024), autores identificados de universidade federal, com referências — usar a fonte B.', 'Nota cheia: aplica pelo menos três critérios às duas fontes e escolhe a B. Metade: escolhe a B com justificativa fraca. Zero: escolhe a A.'),
      (v_atividade, 7, 1, 'Explique o perigo do arquivo "manual-empilhadeira.pdf.exe" e cite outras extensões que merecem desconfiança.', 0.5, 'É um executável disfarçado de PDF (extensão dupla): ao abrir, roda um programa que pode ser vírus/malware e infectar a rede da empresa. Outras extensões suspeitas: .exe, .bat, .scr (e também .msi, .vbs, .js quando inesperados).', 'Nota cheia: identifica o executável disfarçado + cita duas extensões. Metade: só um dos dois. Zero: considera seguro.'),
      (v_atividade, 7, 2, 'Descreva os cuidados ao baixar o manual do portal oficial e onde e com que nome você salvaria o arquivo.', 0.5, 'Baixar só do site oficial (conferir o endereço e o cadeado/HTTPS), analisar com o antivírus antes de abrir e conferir a extensão. Salvar na pasta do projeto com nome semântico, ex.: C:\VALESUL\PESQUISAS\2026-10-02_Manual_Empilhadeira_Fabricante.pdf.', 'Nota cheia: dois cuidados + pasta e nome organizados. Metade: só os cuidados ou só o nome. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Explique por que o colega está errado, citando a Lei 9.610/98.', 0.5, 'Estar disponível na internet não significa ser de domínio público. Pela Lei 9.610/98 (Lei de Direitos Autorais), toda criação (foto, texto, imagem) é protegida, e usar sem autorização ou licença viola a lei. É preciso verificar a licença ou pedir autorização e dar crédito.', 'Nota cheia: refuta o colega + cita a lei e a proteção. Metade: refuta sem citar a lei. Zero: concorda com o colega.'),
      (v_atividade, 8, 2, 'Explique o que a licença CC BY-NC permite e exige e se ela pode ser usada num folheto de venda da empresa.', 0.5, 'CC BY-NC permite usar e adaptar a imagem dando crédito ao autor (BY), mas só para fins não comerciais (NC). Num folheto de venda (uso comercial) não pode ser usada sem autorização do autor; no relatório interno pode, com o crédito.', 'Nota cheia: explica BY e NC + conclui que o folheto comercial não pode. Metade: só um dos dois. Zero: conclusão errada sem explicação.'),
      (v_atividade, 9, 1, 'Identifique o tipo de plágio que o colega cometeu e explique o problema.', 0.4, 'Plágio mosaico: mistura trechos de várias fontes sem referências. É apropriação indevida de obra alheia, viola os direitos autorais, prejudica a credibilidade do relatório e da empresa e impede conferir as informações.', 'Nota cheia: plágio mosaico + problema. Metade: chama apenas de plágio e explica o problema. Zero: não identifica o plágio.'),
      (v_atividade, 9, 2, 'Escreva o trecho como citação direta curta e como citação indireta, no padrão ABNT.', 0.6, 'Direta curta: "A altura máxima de empilhamento deve respeitar a resistência da embalagem inferior" (SOUZA, 2024, p. 12). Indireta: Segundo Souza (2024), o limite de altura da pilha depende de quanto a embalagem de baixo aguenta.', 'Nota cheia: direta entre aspas com autor, ano e página + indireta com as próprias palavras, autor e ano, sem aspas. Metade: uma das duas correta. Zero: nenhuma.'),
      (v_atividade, 10, 1, 'Descreva, em ordem, as quatro etapas do roteiro de pesquisa até a entrega da síntese.', 0.5, '1) Delimitar o tema: palavras-chave, operadores e escopo. 2) Buscar e filtrar resultados em fontes e repositórios confiáveis (por data). 3) Avaliar a credibilidade (CRAAP) e cruzar pelo menos 3 fontes independentes. 4) Redigir a síntese com citações e referências no padrão ABNT.', 'Nota cheia: as quatro etapas na ordem. Metade: três etapas ou fora de ordem. Zero: duas ou menos.'),
      (v_atividade, 10, 2, 'Explique o que é a Política de Uso Aceitável (PUA) e os riscos do programa pirata instalado pelo estagiário.', 0.5, 'A PUA define as regras de uso dos recursos de TI da empresa: uso profissional, proibição de software pirata ou sem licença, monitoramento do tráfego. Riscos: violação de direitos autorais (pirataria), malware/vulnerabilidades na rede, vazamento de dados e sanções ao estagiário (até demissão).', 'Nota cheia: define a PUA + dois riscos. Metade: só um dos dois. Zero: sem relação.');
end $$;
